-- Additional explicit leaf links only; no parent/job/identity/credential restore.
BEGIN;
CREATE FUNCTION public.sandy_tenant_manifest_scalar_v1() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $manifest$
 SELECT $m${"id":"application_scalar_links_v1","format_version":"1.0.0","project_ref":"zmqlyygzqoidkcwdysok","complete_tenant_coverage":false,"external_provider_assets_included":false,"schema_sha256":"cac095467d37d12512669286db8ff394ff3ae323bdc370d50c4f26139a788f6c","row_limit_per_table":1000,"maximum_artifact_bytes":2097152,"maximum_text_characters":10000,"tables":[{"table":"sandy_person_links","owner_column":"owner_customer_id","columns":[{"name":"id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"owner_customer_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"from_person_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"to_person_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"link_type","type":"text","nullable":false,"generated":"","identity":""},{"name":"source","type":"text","nullable":false,"generated":"","identity":""},{"name":"note","type":"text","nullable":true,"generated":"","identity":""},{"name":"created_at","type":"timestamp with time zone","nullable":false,"generated":"","identity":""},{"name":"updated_at","type":"timestamp with time zone","nullable":false,"generated":"","identity":""}],"primary_key":["id"],"order":["id"]},{"table":"sandy_life_document_contexts","owner_column":"owner_customer_id","columns":[{"name":"id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"owner_customer_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"document_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"space_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"area_key","type":"text","nullable":false,"generated":"","identity":""},{"name":"status","type":"text","nullable":false,"generated":"","identity":""},{"name":"classification_source","type":"text","nullable":false,"generated":"","identity":""},{"name":"confidence","type":"numeric","nullable":true,"generated":"","identity":"","encoding":"decimal_string"},{"name":"evidence","type":"text","nullable":true,"generated":"","identity":""},{"name":"created_at","type":"timestamp with time zone","nullable":false,"generated":"","identity":""}],"primary_key":["id"],"order":["id"]},{"table":"sandy_knowledge_links","owner_column":"owner_customer_id","columns":[{"name":"id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"owner_customer_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"document_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"entity_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"relationship_type","type":"text","nullable":false,"generated":"","identity":""},{"name":"evidence_excerpt","type":"text","nullable":true,"generated":"","identity":""},{"name":"confidence","type":"numeric","nullable":true,"generated":"","identity":"","encoding":"decimal_string"},{"name":"created_at","type":"timestamp with time zone","nullable":false,"generated":"","identity":""}],"primary_key":["id"],"order":["id"]},{"table":"sandy_timezone_email_offsets","owner_column":"customer_id","columns":[{"name":"id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"customer_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"message_id","type":"uuid","nullable":false,"generated":"","identity":""},{"name":"offset_minutes","type":"integer","nullable":false,"generated":"","identity":""},{"name":"header_date","type":"text","nullable":false,"generated":"","identity":""},{"name":"observed_at","type":"timestamp with time zone","nullable":false,"generated":"","identity":""}],"primary_key":["id"],"order":["id"]}],"manifest_sha256":"7a19a77fa4f1a7d9cc3a83517a9482ddfdd3d4c91cdc303e0cd18e77ed551435"}$m$::jsonb
$manifest$;
CREATE FUNCTION public.sandy_tenant_manifest_scalar_schema_sha256() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $schema$
WITH selected AS (
 SELECT n.nspname AS schema,c.relname AS name,c.oid,c.relkind,c.relowner,c.relrowsecurity,c.relforcerowsecurity
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relname IN ('sandy_person_links','sandy_life_document_contexts','sandy_knowledge_links','sandy_timezone_email_offsets'
 )
), structure AS (
 SELECT jsonb_agg(jsonb_build_object(
  'schema',s.schema,'name',s.name,'kind',s.relkind,'owner',pg_get_userbyid(s.relowner),
  'rls',s.relrowsecurity,'force_rls',s.relforcerowsecurity,
  'columns',coalesce((SELECT jsonb_agg(jsonb_build_object(
   'position',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
   'nullable',NOT a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,
   'default',pg_get_expr(d.adbin,d.adrelid)
  ) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=s.oid AND a.attnum>0 AND NOT a.attisdropped),'[]'::jsonb),
  'constraints',coalesce((SELECT jsonb_agg(jsonb_build_object(
   'name',k.conname,'kind',k.contype,'definition',pg_get_constraintdef(k.oid),
   'deferrable',k.condeferrable,'initially_deferred',k.condeferred,'validated',k.convalidated
  ) ORDER BY k.conname) FROM pg_constraint k WHERE k.conrelid=s.oid),'[]'::jsonb),
  'incoming_fks',coalesce((SELECT jsonb_agg(jsonb_build_object('name',k.conname,'source',k.conrelid::regclass::text,'definition',pg_get_constraintdef(k.oid),'delete_action',k.confdeltype) ORDER BY k.conrelid::regclass::text,k.conname) FROM pg_constraint k WHERE k.confrelid=s.oid AND k.contype='f'),'[]'::jsonb),
  'triggers',coalesce((SELECT jsonb_agg(jsonb_build_object(
   'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid),
   'function_sha256',encode(extensions.digest(pg_get_functiondef(t.tgfoid),'sha256'),'hex')
  ) ORDER BY t.tgname) FROM pg_trigger t WHERE t.tgrelid=s.oid AND NOT t.tgisinternal),'[]'::jsonb)
 ) ORDER BY s.name) AS document FROM selected s
)
SELECT encode(extensions.digest(document::text,'sha256'),'hex') FROM structure
$schema$;
CREATE FUNCTION public.sandy_tenant_manifest_scalar_parent_check(p_tenant uuid,p_restore boolean) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM public.sandy_person_links x LEFT JOIN public.sandy_people f ON f.id=x.from_person_id AND f.owner_customer_id=p_tenant LEFT JOIN public.sandy_people t ON t.id=x.to_person_id AND t.owner_customer_id=p_tenant WHERE x.owner_customer_id=p_tenant AND (f.id IS NULL OR t.id IS NULL OR (p_restore AND (f.status<>'active' OR t.status<>'active')))) THEN RAISE EXCEPTION 'tenant_person_link_parent_ownership_or_state_refused';END IF;
 IF EXISTS(SELECT 1 FROM public.sandy_life_document_contexts x LEFT JOIN public.sandy_knowledge_documents d ON d.id=x.document_id AND d.owner_customer_id=p_tenant LEFT JOIN public.sandy_life_spaces s ON s.id=x.space_id AND s.owner_customer_id=p_tenant LEFT JOIN public.sandy_life_areas a ON a.area_key=x.area_key WHERE x.owner_customer_id=p_tenant AND (d.id IS NULL OR s.id IS NULL OR a.area_key IS NULL OR (p_restore AND d.status<>'ready'))) THEN RAISE EXCEPTION 'tenant_document_context_parent_ownership_or_state_refused';END IF;
 IF EXISTS(SELECT 1 FROM public.sandy_knowledge_links x LEFT JOIN public.sandy_knowledge_documents d ON d.id=x.document_id AND d.owner_customer_id=p_tenant LEFT JOIN public.sandy_knowledge_entities e ON e.id=x.entity_id AND e.owner_customer_id=p_tenant WHERE x.owner_customer_id=p_tenant AND (d.id IS NULL OR e.id IS NULL OR (p_restore AND d.status<>'ready'))) THEN RAISE EXCEPTION 'tenant_knowledge_link_parent_ownership_or_state_refused';END IF;
 -- No native FK exists for this parent. UUID coincidence never proves ownership.
 IF EXISTS(SELECT 1 FROM public.sandy_timezone_email_offsets x LEFT JOIN public.email_messages m ON m.id=x.message_id AND m.customer_id=p_tenant WHERE x.customer_id=p_tenant AND m.id IS NULL) THEN RAISE EXCEPTION 'tenant_timezone_message_ownership_refused';END IF;
END $$;
CREATE FUNCTION public.sandy_tenant_capture_scalar_v1(p_tenant uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE manifest jsonb:=public.sandy_tenant_manifest_scalar_v1();entry jsonb;col jsonb;column_sql text;select_columns text;order_sql text;bound_sql text;row_data jsonb;tables jsonb:='{}'::jsonb;payload jsonb;row_count integer;overflow boolean;
BEGIN
 IF p_tenant IS NULL OR public.sandy_tenant_manifest_scalar_schema_sha256() IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_manifest_schema_changed';END IF;
 PERFORM public.sandy_tenant_manifest_scalar_parent_check(p_tenant,false);
 FOR entry IN SELECT value FROM jsonb_array_elements(manifest->'tables') LOOP
  EXECUTE format('SELECT count(*) FROM(SELECT 1 FROM public.%I WHERE %I=$1 LIMIT 1001)t',entry->>'table',entry->>'owner_column') INTO row_count USING p_tenant;
  IF row_count>1000 THEN RAISE EXCEPTION 'tenant_manifest_row_bound_exceeded';END IF;
  SELECT string_agg(CASE WHEN c->>'type'='numeric' THEN format('(char_length(t.%I::text)>10000 OR t.%I::text !~ %L)',c->>'name',c->>'name','^-?[0-9]+(\.[0-9]+)?$') ELSE format('char_length(t.%I)>10000',c->>'name') END,' OR ') INTO bound_sql FROM jsonb_array_elements(entry->'columns') c WHERE c->>'type' IN('text','numeric');
  IF bound_sql IS NOT NULL THEN
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I t WHERE t.%I=$1 AND (%s))',entry->>'table',entry->>'owner_column',bound_sql) INTO overflow USING p_tenant;
   IF overflow THEN RAISE EXCEPTION 'tenant_manifest_text_or_decimal_bound_exceeded';END IF;
  END IF;
  column_sql:='';select_columns:='';order_sql:='';
  FOR col IN SELECT value FROM jsonb_array_elements(entry->'columns') LOOP
   column_sql:=column_sql||CASE WHEN column_sql='' THEN '' ELSE ',' END||format('%L,t.%I%s',col->>'name',col->>'name',CASE WHEN col->>'encoding'='decimal_string' THEN '::text' ELSE '' END);
   select_columns:=select_columns||CASE WHEN select_columns='' THEN '' ELSE ',' END||format('%I',col->>'name');
  END LOOP;
  SELECT string_agg(format('t.%I',k.value),',' ORDER BY k.position) INTO order_sql FROM jsonb_array_elements_text(entry->'order') WITH ORDINALITY k(value,position);
  EXECUTE format('SELECT coalesce(jsonb_agg(jsonb_build_object(%s) ORDER BY %s),''[]''::jsonb) FROM(SELECT %s FROM public.%I WHERE %I=$1 ORDER BY %s LIMIT 1001)t',column_sql,order_sql,select_columns,entry->>'table',entry->>'owner_column',replace(order_sql,'t.','')) INTO row_data USING p_tenant;
  IF jsonb_array_length(row_data)>1000 THEN RAISE EXCEPTION 'tenant_manifest_row_bound_exceeded';END IF;
  tables:=tables||jsonb_build_object(entry->>'table',row_data);
 END LOOP;
 payload:=jsonb_build_object('format_version','1.0.0','tenant_id',p_tenant,'manifest',manifest->>'id','manifest_sha256',manifest->>'manifest_sha256','schema_sha256',manifest->>'schema_sha256','complete_tenant_coverage',false,'external_provider_assets_included',false,'tables',tables);
 IF octet_length(payload::text)>2097152 THEN RAISE EXCEPTION 'tenant_manifest_artifact_bound_exceeded';END IF;
 RETURN payload;
END $$;
CREATE FUNCTION public.sandy_tenant_lifecycle_operation_config(p_operation text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT $config${"supabase.tenant.export":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"export"},"supabase.tenant.manifests.export":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"export"},"supabase.tenant.erase":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"erase"},"supabase.tenant.manifests.erase":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"erase"},"supabase.tenant.restore":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"restore"},"supabase.tenant.manifests.restore":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"restore"},"supabase.tenant.exports.get":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"get"},"supabase.tenant.manifests.exports.get":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"get"},"supabase.tenant.exports.purge":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"purge"},"supabase.tenant.manifests.exports.purge":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"purge"},"supabase.tenant.protected_resources.inventory":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"inventory"}}$config$::jsonb->p_operation
$$;
CREATE FUNCTION public.sandy_tenant_manifest_resolve(p_manifest text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_manifest='application_leaf_links_v1' THEN RETURN public.sandy_tenant_manifest_v1();
 ELSIF p_manifest='application_scalar_links_v1' THEN RETURN public.sandy_tenant_manifest_scalar_v1();
 ELSE RAISE EXCEPTION 'tenant_manifest_not_supported';END IF;
END $$;
CREATE FUNCTION public.sandy_tenant_capture_manifest(p_manifest text,p_tenant uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_manifest='application_leaf_links_v1' THEN RETURN public.sandy_tenant_capture_v1(p_tenant);
 ELSIF p_manifest='application_scalar_links_v1' THEN RETURN public.sandy_tenant_capture_scalar_v1(p_tenant);
 ELSE RAISE EXCEPTION 'tenant_manifest_not_supported';END IF;
END $$;
CREATE FUNCTION public.sandy_tenant_manifest_parents(p_manifest text,p_tenant uuid,p_restore boolean) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_manifest='application_leaf_links_v1' THEN PERFORM public.sandy_tenant_manifest_parent_check(p_tenant,p_restore);
 ELSIF p_manifest='application_scalar_links_v1' THEN PERFORM public.sandy_tenant_manifest_scalar_parent_check(p_tenant,p_restore);
 ELSE RAISE EXCEPTION 'tenant_manifest_not_supported';END IF;
END $$;
DO $$ BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_lifecycle_context(uuid,uuid,text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '80e1c2b5d8c13325065ae4021748470dbd11e48c787badfa324b98ca59cb8dd9' THEN RAISE EXCEPTION 'tenant_scalar_prior_context_source_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_lifecycle_context(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE a public.sandy_api_execution_admissions;r public.sandy_operation_registry;c public.sandy_supabase_tenant_consents;controls public.sandy_supabase_tenant_controls;args jsonb;tenant uuid;manifest jsonb;config jsonb;
BEGIN
 IF p_actor IS NULL OR p_admission IS NULL OR p_canonical IS NULL OR octet_length(p_canonical)>196608 THEN RAISE EXCEPTION 'tenant_lifecycle_context_invalid';END IF;
 args:=p_canonical::jsonb;tenant:=(args->>'tenant_id')::uuid;
 SELECT * INTO a FROM public.sandy_api_execution_admissions WHERE id=p_admission FOR UPDATE;
 config:=public.sandy_tenant_lifecycle_operation_config(a.operation);
 IF a.id IS NULL OR a.actor_id IS DISTINCT FROM p_actor OR a.tenant_id IS NOT NULL OR a.credential_id IS NOT NULL OR a.approval_id IS NULL OR a.state IS DISTINCT FROM 'consumed' OR a.expires_at<=clock_timestamp() OR NOT public.sandy_api_current_owner(p_actor)
 OR a.input_sha256 IS DISTINCT FROM encode(extensions.digest(p_canonical,'sha256'),'hex') OR config IS NULL OR a.scope_sha256 IS DISTINCT FROM config->>'scope_sha256' THEN RAISE EXCEPTION 'tenant_lifecycle_scoped_owner_admission_required';END IF;
 manifest:=public.sandy_tenant_manifest_resolve(config->>'manifest');
 SELECT * INTO r FROM public.sandy_operation_registry WHERE operation=a.operation FOR SHARE;
 IF r.operation IS NULL OR r.handler IS DISTINCT FROM 'sandy-tenant-lifecycle-api' OR r.api_exposed IS DISTINCT FROM true OR r.verified IS DISTINCT FROM true OR r.is_mutation IS DISTINCT FROM a.is_mutation
 OR r.error_contract->>'requires_approval' IS DISTINCT FROM 'true' OR r.error_contract->>'api_key_delegable' IS DISTINCT FROM 'false' OR r.error_contract->>'contract_sha256' IS DISTINCT FROM a.contract_sha256 OR public.sandy_api_registry_revision(a.operation) IS DISTINCT FROM a.registry_revision_sha256 THEN RAISE EXCEPTION 'tenant_lifecycle_current_verified_contract_required';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_api_mutation_approval_snapshots proof JOIN public.sandy_deployment_jobs job ON job.id=proof.job_id JOIN public.sandy_engineering_changes change ON change.id=proof.engineering_change_id
 WHERE proof.job_id=a.approval_id AND proof.actor_id=p_actor AND proof.operation=a.operation AND proof.input_sha256=a.input_sha256 AND proof.contract_sha256=a.contract_sha256 AND proof.scope_sha256=a.scope_sha256
 AND a.declared_cost_units<=proof.maximum_declared_cost_units AND job.status='running' AND change.status='approved' AND proof.job_fingerprint_sha256=public.sandy_api_job_fingerprint(job)) THEN RAISE EXCEPTION 'immutable_scoped_owner_approval_required';END IF;
 SELECT * INTO c FROM public.sandy_supabase_tenant_consents WHERE tenant_id=tenant FOR SHARE;
 SELECT * INTO controls FROM public.sandy_supabase_tenant_controls WHERE tenant_id=tenant FOR SHARE;
 IF c.tenant_id IS NULL OR c.expires_at<=clock_timestamp() OR public.sandy_supabase_portal_tenant(c.auth_user_id) IS DISTINCT FROM tenant OR NOT a.operation=ANY(c.operations) THEN RAISE EXCEPTION 'tenant_lifecycle_explicit_consent_required';END IF;
 IF args ? 'manifest' AND (args->>'manifest' IS DISTINCT FROM manifest->>'id' OR args->>'expected_manifest_sha256' IS DISTINCT FROM manifest->>'manifest_sha256') THEN RAISE EXCEPTION 'tenant_lifecycle_manifest_mismatch';END IF;
 IF config->>'action' IN('erase','restore','purge') AND (c.allow_erasure IS DISTINCT FROM true OR controls.legal_hold IS TRUE OR controls.retention_until>clock_timestamp()) THEN RAISE EXCEPTION 'tenant_lifecycle_hold_or_retention_refused';END IF;
 RETURN jsonb_build_object('operation',a.operation,'tenant_id',tenant,'arguments',args,'manifest',manifest->>'id','action',config->>'action');
END $$;
DO $$ BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_lifecycle_execute(uuid,uuid,text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '9d654d10a40550bde2ea2e05b939170ac3d4234564cfb5faefc961d7458483ef' THEN RAISE EXCEPTION 'tenant_scalar_prior_execute_source_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_lifecycle_execute(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE ctx jsonb;args jsonb;tenant uuid;op text;action text;manifest jsonb;owner_column text;snapshot public.sandy_tenant_export_snapshots;payload jsonb;before_data jsonb;after_data jsonb;before_hash text;after_hash text;result jsonb;existing_result jsonb;counts jsonb;snapshot_id uuid;vault_id uuid;material text;entry jsonb;col jsonb;columns_sql text;record_sql text;compare_sql text;select_sql text;rows jsonb;affected integer;expected integer;
BEGIN
 ctx:=public.sandy_tenant_lifecycle_context(p_actor,p_admission,p_canonical);args:=ctx->'arguments';tenant:=(ctx->>'tenant_id')::uuid;op:=ctx->>'operation';action:=ctx->>'action';manifest:=public.sandy_tenant_manifest_resolve(ctx->>'manifest');
 SELECT receipt.result INTO existing_result FROM public.sandy_tenant_lifecycle_receipts receipt WHERE receipt.admission_id=p_admission;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'result',existing_result,'reused',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('tenant_manifest_lifecycle:'||tenant::text,0));
 IF action='export' THEN
  payload:=public.sandy_tenant_capture_manifest(manifest->>'id',tenant);before_hash:=encode(extensions.digest(payload::text,'sha256'),'hex');snapshot_id:=gen_random_uuid();
  SELECT jsonb_object_agg(e.key,jsonb_array_length(e.value)) INTO counts FROM jsonb_each(payload->'tables') e;
  SELECT vault.create_secret(payload::text,'sandy_tenant_export_v1_'||snapshot_id::text,'Private explicitly bounded tenant application leaf-link export') INTO vault_id;
  INSERT INTO public.sandy_tenant_export_snapshots(id,tenant_id,manifest,manifest_sha256,schema_sha256,snapshot_sha256,row_counts,vault_secret_id,source_admission_id,expires_at)
  VALUES(snapshot_id,tenant,manifest->>'id',manifest->>'manifest_sha256',manifest->>'schema_sha256',before_hash,counts,vault_id,p_admission,clock_timestamp()+interval '24 hours') RETURNING * INTO snapshot;
  SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=vault_id;
  IF material IS DISTINCT FROM payload::text THEN RAISE EXCEPTION 'tenant_export_encryption_readback_failed';END IF;
  result:=public.sandy_tenant_snapshot_metadata(snapshot);
 ELSE
  SELECT * INTO snapshot FROM public.sandy_tenant_export_snapshots WHERE id=(args->>'snapshot_id')::uuid AND tenant_id=tenant FOR UPDATE;
  IF snapshot.id IS NULL THEN RAISE EXCEPTION 'tenant_export_not_found';END IF;
  IF snapshot.manifest IS DISTINCT FROM manifest->>'id' OR snapshot.manifest_sha256 IS DISTINCT FROM manifest->>'manifest_sha256' OR snapshot.schema_sha256 IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_export_manifest_version_unsupported';END IF;
  IF action='get' THEN result:=public.sandy_tenant_snapshot_metadata(snapshot);
  ELSIF action='purge' THEN
   IF args->>'confirm_artifact_purge' IS DISTINCT FROM 'true' OR snapshot.state='purged' OR snapshot.vault_secret_id IS NULL OR EXISTS(SELECT 1 FROM public.sandy_credential_versions WHERE vault_secret_id=snapshot.vault_secret_id) THEN RAISE EXCEPTION 'tenant_export_purge_refused';END IF;
   before_hash:=snapshot.snapshot_sha256;
   DELETE FROM vault.secrets WHERE id=snapshot.vault_secret_id AND name='sandy_tenant_export_v1_'||snapshot.id::text;
   IF NOT FOUND OR EXISTS(SELECT 1 FROM vault.secrets WHERE id=snapshot.vault_secret_id) THEN RAISE EXCEPTION 'tenant_export_purge_readback_failed';END IF;
   UPDATE public.sandy_tenant_export_snapshots SET state='purged',vault_secret_id=NULL WHERE id=snapshot.id RETURNING * INTO snapshot;
   result:=public.sandy_tenant_snapshot_metadata(snapshot)||jsonb_build_object('readback_verified',true);
  ELSIF action IN('erase','restore') THEN
   IF snapshot.expires_at<=clock_timestamp() OR snapshot.vault_secret_id IS NULL OR snapshot.state='purged' THEN RAISE EXCEPTION 'tenant_export_expired_or_purged';END IF;
   IF (action='erase' AND (args->>'confirm_manifest_erasure' IS DISTINCT FROM 'true' OR snapshot.state NOT IN('exported','restored')))
   OR (action='restore' AND (args->>'confirm_manifest_restore' IS DISTINCT FROM 'true' OR snapshot.state<>'erased')) THEN RAISE EXCEPTION 'tenant_manifest_state_or_confirmation_refused';END IF;
   SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=snapshot.vault_secret_id AND name='sandy_tenant_export_v1_'||snapshot.id::text;
   IF material IS NULL OR octet_length(material)>2097152 OR encode(extensions.digest(material,'sha256'),'hex') IS DISTINCT FROM snapshot.snapshot_sha256 THEN RAISE EXCEPTION 'tenant_export_artifact_integrity_failed';END IF;
   payload:=material::jsonb;
   IF payload->>'tenant_id' IS DISTINCT FROM tenant::text OR payload->>'manifest_sha256' IS DISTINCT FROM manifest->>'manifest_sha256' OR payload->>'schema_sha256' IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_export_artifact_scope_failed';END IF;
   before_data:=public.sandy_tenant_capture_manifest(manifest->>'id',tenant);before_hash:=encode(extensions.digest(before_data::text,'sha256'),'hex');
   IF args->>'expected_current_sha256' IS DISTINCT FROM before_hash THEN RAISE EXCEPTION 'tenant_manifest_current_state_changed';END IF;
   IF action='erase' AND before_hash IS DISTINCT FROM snapshot.snapshot_sha256 THEN RAISE EXCEPTION 'tenant_export_stale_erasure_refused';END IF;
   IF action='restore' AND EXISTS(SELECT 1 FROM jsonb_each(before_data->'tables') e WHERE jsonb_array_length(e.value)<>0) THEN RAISE EXCEPTION 'tenant_restore_requires_empty_manifest';END IF;
   FOR entry IN SELECT value FROM jsonb_array_elements(manifest->'tables') LOOP
    rows:=payload->'tables'->(entry->>'table');expected:=jsonb_array_length(rows);owner_column:=coalesce(entry->>'owner_column','customer_id');
    IF rows IS NULL OR expected>1000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE r->>owner_column IS DISTINCT FROM tenant::text) THEN RAISE EXCEPTION 'tenant_export_row_scope_failed';END IF;
    columns_sql:='';record_sql:='';compare_sql:='';select_sql:='';
    FOR col IN SELECT value FROM jsonb_array_elements(entry->'columns') LOOP
     IF coalesce(col->>'generated','')='' AND coalesce(col->>'identity','')='' THEN
      columns_sql:=columns_sql||CASE WHEN columns_sql='' THEN '' ELSE ',' END||format('%I',col->>'name');
      select_sql:=select_sql||CASE WHEN select_sql='' THEN '' ELSE ',' END||format('r.%I',col->>'name');
     END IF;
     record_sql:=record_sql||CASE WHEN record_sql='' THEN '' ELSE ',' END||format('%I %s',col->>'name',col->>'type');
     compare_sql:=compare_sql||CASE WHEN compare_sql='' THEN '' ELSE ' AND ' END||format('t.%I IS NOT DISTINCT FROM r.%I',col->>'name',col->>'name');
    END LOOP;
    IF action='erase' THEN
     -- Delete only exact captured rows. Concurrent changes skip the comparison
     -- and fail the row-count/postcondition check; no unseen row is removed.
     EXECUTE format('DELETE FROM public.%I t USING jsonb_to_recordset($1) AS r(%s) WHERE t.%I=$2 AND %s',entry->>'table',record_sql,owner_column,compare_sql) USING rows,tenant;
    ELSE
     -- Server-captured typed values only. Unique/PK conflicts abort, with no
     -- upsert, parent insertion, role/access restoration or task row writes.
     EXECUTE format('INSERT INTO public.%I(%s) SELECT %s FROM jsonb_to_recordset($1) AS r(%s) WHERE r.%I=$2',entry->>'table',columns_sql,select_sql,record_sql,owner_column) USING rows,tenant;
    END IF;
    GET DIAGNOSTICS affected=ROW_COUNT;
    IF affected<>expected THEN RAISE EXCEPTION 'tenant_manifest_row_compare_conflict';END IF;
   END LOOP;
   IF action='restore' THEN PERFORM public.sandy_tenant_manifest_parents(manifest->>'id',tenant,true);END IF;
   after_data:=public.sandy_tenant_capture_manifest(manifest->>'id',tenant);after_hash:=encode(extensions.digest(after_data::text,'sha256'),'hex');
   IF (action='erase' AND EXISTS(SELECT 1 FROM jsonb_each(after_data->'tables') e WHERE jsonb_array_length(e.value)<>0)) OR (action='restore' AND after_hash IS DISTINCT FROM snapshot.snapshot_sha256) THEN RAISE EXCEPTION 'tenant_manifest_postcondition_failed';END IF;
   UPDATE public.sandy_tenant_export_snapshots SET state=CASE WHEN action='erase' THEN 'erased' ELSE 'restored' END,
    erased_admission_id=CASE WHEN action='erase' THEN p_admission ELSE erased_admission_id END,
    restored_admission_id=CASE WHEN action='restore' THEN p_admission ELSE restored_admission_id END WHERE id=snapshot.id RETURNING * INTO snapshot;
   result:=public.sandy_tenant_snapshot_metadata(snapshot)||jsonb_build_object('before_sha256',before_hash,'after_sha256',after_hash,'readback_verified',true,'scope',CASE WHEN action='erase' THEN 'exact_snapshot_manifest_rows' ELSE 'empty_target_manifest_only' END);
  ELSE RAISE EXCEPTION 'tenant_lifecycle_operation_not_implemented';END IF;
 END IF;
 INSERT INTO public.sandy_tenant_lifecycle_receipts(admission_id,snapshot_id,result) VALUES(p_admission,snapshot.id,result);
 INSERT INTO public.sandy_tenant_lifecycle_events(tenant_id,snapshot_id,actor_id,admission_id,operation,before_sha256,after_sha256) VALUES(tenant,snapshot.id,p_actor,p_admission,op,before_hash,after_hash);
 RETURN jsonb_build_object('ok',true,'result',result,'reused',false);
END $$;
DO $$ DECLARE definition text;BEGIN
 SELECT pg_get_constraintdef(oid) INTO definition FROM pg_constraint WHERE conrelid='public.sandy_tenant_export_snapshots'::regclass AND conname='sandy_tenant_export_snapshots_manifest_check';
 IF definition IS DISTINCT FROM 'CHECK ((manifest = ''application_leaf_links_v1''::text))' THEN RAISE EXCEPTION 'tenant_scalar_prior_snapshot_manifest_check_changed';END IF;
END $$;
ALTER TABLE public.sandy_tenant_export_snapshots DROP CONSTRAINT sandy_tenant_export_snapshots_manifest_check;
ALTER TABLE public.sandy_tenant_export_snapshots ADD CONSTRAINT sandy_tenant_export_snapshots_manifest_check CHECK(manifest IN('application_leaf_links_v1','application_scalar_links_v1'));
DO $$ BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_export_download(uuid)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '9500c226e15e11b4a63b223aed115f0b599922795e7bf35850f4c858130ad086' THEN RAISE EXCEPTION 'tenant_scalar_prior_download_source_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_export_download(p_snapshot uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE tenant uuid:=public.sandy_supabase_portal_tenant(auth.uid());snapshot public.sandy_tenant_export_snapshots;material text;payload jsonb;manifest jsonb;
BEGIN
 IF tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'error','confirmed_portal_customer_session_required','http_status',403);END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation='supabase.tenant.exports.download' AND handler='sandy-operation-api' AND api_exposed AND verified AND error_contract->>'requires_real_user_session'='true') THEN RETURN jsonb_build_object('ok',false,'error','verified_tenant_export_download_required','http_status',424);END IF;
 SELECT * INTO snapshot FROM public.sandy_tenant_export_snapshots WHERE id=p_snapshot AND tenant_id=tenant FOR SHARE;
 IF snapshot.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','tenant_export_not_found','http_status',404);END IF;
 IF snapshot.expires_at<=clock_timestamp() OR snapshot.state='purged' OR snapshot.vault_secret_id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','tenant_export_expired_or_purged','http_status',410);END IF;
 SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=snapshot.vault_secret_id AND name='sandy_tenant_export_v1_'||snapshot.id::text;
 IF material IS NULL OR octet_length(material)>2097152 OR encode(extensions.digest(material,'sha256'),'hex') IS DISTINCT FROM snapshot.snapshot_sha256 THEN RAISE EXCEPTION 'tenant_export_artifact_integrity_failed';END IF;
 manifest:=public.sandy_tenant_manifest_resolve(snapshot.manifest);
 IF snapshot.manifest_sha256 IS DISTINCT FROM manifest->>'manifest_sha256' OR snapshot.schema_sha256 IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_export_manifest_version_unsupported';END IF;
 payload:=material::jsonb;
 IF payload->>'manifest' IS DISTINCT FROM manifest->>'id' OR payload->>'tenant_id' IS DISTINCT FROM tenant::text OR payload->>'manifest_sha256' IS DISTINCT FROM snapshot.manifest_sha256 OR payload->>'schema_sha256' IS DISTINCT FROM snapshot.schema_sha256 OR payload->>'complete_tenant_coverage' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'tenant_export_artifact_scope_failed';END IF;
 INSERT INTO public.sandy_tenant_lifecycle_events(tenant_id,snapshot_id,actor_id,operation,before_sha256,after_sha256) VALUES(tenant,snapshot.id,auth.uid(),'supabase.tenant.exports.download',snapshot.snapshot_sha256,snapshot.snapshot_sha256);
 RETURN jsonb_build_object('ok',true,'snapshot_id',snapshot.id,'snapshot_sha256',snapshot.snapshot_sha256,'file_name','sandy-tenant-links-'||snapshot.id::text||'.json','export',payload);
END $$;
